/* ===== module: share-shortlinks.js ===== */
    /* Server-backed short links for shares (#177, user 2026-09-12).
       When SIGNED IN, sharing a workout/program mints a short link
       https://kohlrabi.us/s/<slug> backed by the
       public.share_links table (see supabase/migrations/0001_share_links.sql
       — the user runs the migration separately; the app degrades gracefully
       when the table is absent). The payload column holds the exact v2
       compressed string long links use, so opening a short link decodes
       through shareDecodeAny and lands on the SAME share preview/modal as
       long links. Slugs are client-generated: 8 chars from
       crypto.getRandomValues over [a-zA-Z0-9]; a unique-violation retries
       with a fresh slug (5 tries), then the flow falls back to the long
       link. Signed-out shares — and ANY failure — keep the existing long
       compressed-link behavior untouched: sharing never breaks.
       Static-host routing: GitHub Pages has no rewrites, so /s/<slug> is
       served by 404.html, which stashes the path in sessionStorage and
       hands off to index.html; boot consumes it here (one-shot). */
       /* Module map (v1.014) — Key: newShareSlug()/isValidShareSlug(),
          buildShortShareUrl(), tryShortShareLink(),
          lastShortLinkFailureReason() (2026-09-23: mint-failure diagnostics),
          shortSlugFromPath(),
          shortLinkAttemptFromPath() (#177 follow-up),
          resolveShortShareLink(), clearShortSharePath(),
          takeSpaRedirectSlug(), spaBaseForPath(). Depends on: share-codec
          (shareDecodeAny, validSharePayload — loads just before), Sync
          namespace (getSupabase — sync-adapter.js, loads earlier). No DOM
          at load time. */
    const SHARE_SHORT_ORIGIN='https://kohlrabi.us';
    const SHARE_SLUG_ALPHABET='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    const SHARE_SLUG_LENGTH=8;
    const SHARE_SHORT_MAX_ATTEMPTS=5;
    /* 2026-09-23: transient network hiccups (TypeError: Load failed on the
       phone) intermittently kill the insert — one manual retry fixed it, so
       the app now retries automatically with the same slug. */
    const SHARE_SHORT_INSERT_RETRIES=2;
    const SHARE_SHORT_RETRY_DELAY_MS=800;
    /* True when an insert failure message looks like a transient network
       problem worth retrying (as opposed to a real rejection like RLS). */
    function isTransientShortLinkError(msg){
      return /load failed|failed to fetch|networkerror|network request failed|timed?\s?out|abort/i.test(String(msg||''));
    }
    /* sessionStorage key the 404.html SPA fallback uses to hand the
       requested path to index.html. The inline copy in 404.html hardcodes
       the same string — keep them in sync. */
    const SPA_REDIRECT_KEY='cg-spa-redirect';

    /* ---- Slug generation ---- */
    /* DSA-13 (v1.997.41): rejection sampling — 248 is the largest
       multiple of 62 that fits in a byte, so bytes >= 248 are discarded
       instead of mapped with % 62 (which biased the first 8 alphabet
       characters). Accepted bytes map uniformly onto the alphabet. */
    const SHARE_SLUG_REJECT_AT=248;
    function shareSlugFromBytes(bytes){
      let s='';
      for(let i=0;i<bytes.length;i++){
        if(bytes[i]>=SHARE_SLUG_REJECT_AT)continue;
        s+=SHARE_SLUG_ALPHABET[bytes[i]%SHARE_SLUG_ALPHABET.length];
      }
      return s;
    }
    /* True for an 8-char alphanumeric share slug. */
    function isValidShareSlug(s){
      return typeof s==='string'&&/^[A-Za-z0-9]{8}$/.test(s);
    }
    /* Mints a cryptographically random share slug. */
    function newShareSlug(){
      const g=(typeof globalThis!=='undefined')?globalThis:{};
      const c=g.crypto;
      if(!c||typeof c.getRandomValues!=='function')throw new Error('no secure RNG for share slug');
      /* DSA-13: draw replacements for rejected bytes until the slug
         reaches its full length. */
      let s='';
      while(s.length<SHARE_SLUG_LENGTH){
        const bytes=new Uint8Array(SHARE_SLUG_LENGTH-s.length);
        c.getRandomValues(bytes);
        s+=shareSlugFromBytes(bytes);
      }
      return s;
    }
    /* Builds the short URL for a slug (origin + /s/<slug>). */
    function buildShortShareUrl(slug){
      return SHARE_SHORT_ORIGIN+'/s/'+slug;
    }

    /* ---- Signed-in + Supabase access (best-effort) ---- */
    function shortLinksSignedIn(){
      /* share.js owns the canonical check; fall back to the raw globals so
         this module stays testable standalone. */
      if(typeof shareSignedIn==='function'){try{return !!shareSignedIn();}catch(_){}}
      try{if(typeof lastAuthUid!=='undefined'&&lastAuthUid)return true;}catch(_){}
      try{return !!((typeof Sync!=='undefined'&&Sync&&Sync.lastAuthUid)||(typeof window!=='undefined'&&window.Sync&&window.Sync.lastAuthUid));}catch(_){return false;}
    }
    /* Supabase client for short links, or a resolving null. */
    function shortLinksSupabase(){
      try{
        if(typeof Sync!=='undefined'&&Sync&&typeof Sync.getSupabase==='function')return Sync.getSupabase();
      }catch(_){}
      return Promise.resolve(null);
    }

    /* ---- Mint failure diagnostics ----
       tryShortShareLink never throws — but it used to swallow WHY it fell
       back to the long link, which made a production mint failure
       undebuggable (2026-09-23: signed-in shares silently minted long
       links). The last failure reason is recorded here for the caller to
       surface in the dialog and the console. Reason codes: signed-out,
       no-code, no-client, no-session (stale signed-in flag, dead Supabase
       session), rng, insert:<code> (Supabase error), insert-threw,
       collisions. */
    let lastShortLinkFailure='';
    /* The reason the last tryShortShareLink call fell back ('' on success
       or when never attempted). */
    function lastShortLinkFailureReason(){return lastShortLinkFailure;}
    function noteShortLinkFailure(reason){
      lastShortLinkFailure=reason||'';
      try{if(reason&&typeof console!=='undefined'&&console.warn)console.warn('[share] short link failed:',reason);}catch(_){}
    }

    /* #637 (pre-2.0): one live link per shared thing. Sharing the same
       content again used to mint a fresh slug (and a fresh share_links
       row) every time. A small local memo remembers the slug minted for
       each (account, kind, content hash); the next share of identical
       content reuses it after a cheap public read confirms the row still
       exists (a vanished row is forgotten and a fresh slug is minted).
       Content that changed (an edited log, a renamed template) hashes
       differently and gets its own link, since the old link still shows
       the old content. Capped so the memo stays tiny. */
    const SHARE_SLUG_MEMO_KEY='kohlrabi-share-slugs';
    const SHARE_SLUG_MEMO_MAX=200;
    function readShareSlugMemo(){
      try{const raw=localStorage.getItem(SHARE_SLUG_MEMO_KEY);const m=raw?JSON.parse(raw):null;return (m&&typeof m==='object'&&!Array.isArray(m))?m:{};}catch(_){return {};}
    }
    function writeShareSlugMemo(key,slug){
      try{
        const m=readShareSlugMemo();
        delete m[key];
        if(slug)m[key]=slug;
        const keys=Object.keys(m);
        for(let i=0;i<keys.length-SHARE_SLUG_MEMO_MAX;i++)delete m[keys[i]];
        localStorage.setItem(SHARE_SLUG_MEMO_KEY,JSON.stringify(m));
      }catch(_){}
    }
    function shareSlugMemoKey(userId,kind,code){
      return String(userId)+':'+kind+':'+(typeof cyrb53==='function'?cyrb53(code):code.length+':'+code.slice(0,64));
    }
    function clearShareSlugMemo(){try{localStorage.removeItem(SHARE_SLUG_MEMO_KEY);}catch(_){}}

    /* ---- Minting: signed-in shares get the short link, else null ---- */
    async function tryShortShareLink(payload,code){
      /* Returns the short URL, or null when the long link should be used
         instead (signed out, no Supabase client, dead session, insert
         failure, or 5 slug collisions). Never throws — sharing never
         breaks. The fallback reason is available via
         lastShortLinkFailureReason(). */
      lastShortLinkFailure='';
      try{
        if(!shortLinksSignedIn()){noteShortLinkFailure('signed-out');return null;}
        if(!code||typeof code!=='string'){noteShortLinkFailure('no-code');return null;}
        const sb=await shortLinksSupabase();
        if(!sb){noteShortLinkFailure('no-client');return null;}
        /* The app can believe it is signed in (Sync.lastAuthUid set) while
           the Supabase session is actually gone (expired, cleared) — the
           insert would then fail RLS as anonymous. Verify the session is
           live before minting: one re-check guards the client-init race,
           then a missing session is a genuinely dead one. */
        let sessionUser=null;
        try{
          const r1=await sb.auth.getSession();
          sessionUser=r1&&r1.data&&r1.data.session&&r1.data.session.user?r1.data.session.user:null;
          if(!sessionUser){
            await new Promise(r=>setTimeout(r,600));
            const r2=await sb.auth.getSession();
            sessionUser=r2&&r2.data&&r2.data.session&&r2.data.session.user?r2.data.session.user:null;
          }
        }catch(_){sessionUser=null;}
        if(!sessionUser){noteShortLinkFailure('no-session');return null;}
        const kind=(payload&&payload.kind==='program')?'program':'workout';
        const memoKey=shareSlugMemoKey(sessionUser.id,kind,code);
        const known=readShareSlugMemo()[memoKey];
        if(known&&isValidShareSlug(known)){
          try{
            const res=await sb.from('share_links').select('slug').eq('slug',known).maybeSingle();
            if(res&&!res.error&&res.data)return buildShortShareUrl(known);
            if(res&&!res.error&&!res.data)writeShareSlugMemo(memoKey,null); /* row gone — mint fresh */
            else return buildShortShareUrl(known); /* lookup failed: the link was live when minted */
          }catch(_){return buildShortShareUrl(known);}
        }
        for(let attempt=0;attempt<SHARE_SHORT_MAX_ATTEMPTS;attempt++){
          let slug;
          try{slug=newShareSlug();}catch(_){noteShortLinkFailure('rng');return null;}
          /* Insert with automatic retries on transient network failures —
             a fresh slug only helps collisions, not a dead connection. */
          let retryOutcome=null;
          for(let ins=0;ins<=SHARE_SHORT_INSERT_RETRIES;ins++){
            if(ins>0)await new Promise(r=>setTimeout(r,SHARE_SHORT_RETRY_DELAY_MS));
            try{
              const res=await sb.from('share_links').insert({slug,kind,payload:code});
              const err=res&&res.error;
              if(!err){writeShareSlugMemo(memoKey,slug);return buildShortShareUrl(slug);}
              /* Unique-violation retries with a fresh slug; anything else stops. */
              if(err.code==='23505'){retryOutcome='collision';break;}
              const msg=String((err&&err.message)||'');
              if(isTransientShortLinkError(msg)){
                retryOutcome={kind:'transient',msg};
                if(ins<SHARE_SHORT_INSERT_RETRIES)continue;
                break; /* retries exhausted */
              }
              noteShortLinkFailure('insert:'+(err.code||'?')+(msg?':'+msg.slice(0,80):''));
              return null;
            }catch(ex){
              const m=String((ex&&ex.message)||ex||'');
              if(isTransientShortLinkError(m)){
                retryOutcome={kind:'transient',msg:m};
                if(ins<SHARE_SHORT_INSERT_RETRIES)continue;
                break; /* retries exhausted */
              }
              noteShortLinkFailure('insert-threw:'+m.slice(0,80));
              return null;
            }
          }
          if(retryOutcome==='collision')continue; /* try a fresh slug */
          if(retryOutcome&&retryOutcome.kind==='transient'){
            noteShortLinkFailure('insert-retry:'+String(retryOutcome.msg||'').slice(0,80));
            return null;
          }
        }
        noteShortLinkFailure('collisions');
        return null; /* 5 collisions — keep the long link */
      }catch(_){noteShortLinkFailure('unexpected');return null;}
    }

    /* ---- Opening: /s/<slug> → payload ---- */
    const SHORT_SHARE_PATH_RE=/(?:^|\/)s\/([A-Za-z0-9]{8})\/?$/;
    /* Extracts the /s/<slug> slug from a path, or null. */
    function shortSlugFromPath(pathname){
      const m=SHORT_SHARE_PATH_RE.exec(pathname||'');
      return m?m[1]:null;
    }
    /* #177 follow-up (user 2026-09-12): distinguishes "a /s/... route with
       an invalid slug" from "no short-link route at all". Matches ANY single
       /s/<segment> — malformed, unknown, or corrupt — so every attempted
       short link takes the invalid-link feedback path instead of silently
       opening Home. */
    const SHORT_SHARE_ATTEMPT_RE=/(?:^|\/)s\/([^\/]+)\/?$/;
    /* Extracts the /s/<segment> attempt (valid or not), or null. */
    function shortLinkAttemptFromPath(pathname){
      const m=SHORT_SHARE_ATTEMPT_RE.exec(pathname||'');
      return m?m[1]:null;
    }
    /* Looks up a slug's payload in Supabase (one retry); null on any failure. */
    async function resolveShortShareLink(slug){
      /* Fetches the row and runs the payload through the EXISTING v2
         decoder + validator. Unknown slug, missing table, offline — all
         resolve to null and the caller shows the standard invalid-link
         feedback. Never throws.
         2026-09-13: a transient Supabase 504 (CORS-blocked, so the fetch
         rejects) killed a valid cold-opened link with no retry. One retry
         on request failure; an unknown slug (no rows, no error) is NOT
         retried — it takes the invalid-link path immediately. */
      try{
        if(!isValidShareSlug(slug))return null;
        const sb=await shortLinksSupabase();
        if(!sb)return null;
        let res=null;
        for(let attempt=0;attempt<2;attempt++){
          try{
            res=await sb.from('share_links').select('payload').eq('slug',slug).maybeSingle();
            break;
          }catch(_){
            res=null;
            if(attempt===0)await new Promise(r=>setTimeout(r,700));
          }
        }
        const data=res&&res.data, error=res&&res.error;
        if(error||!data||typeof data.payload!=='string')return null;
        const payload=await shareDecodeAny(data.payload);
        if(!validSharePayload(payload))return null;
        return payload;
      }catch(_){return null;}
    }
    /* Strips the /s/<slug> suffix from the URL after acting on a short link. */
    function clearShortSharePath(){
      /* Mirrors clearShareHash: after acting on (or dismissing) a short-link
         share, drop the /s/<slug> suffix so a reload doesn't re-offer it.
         #177 follow-up: also clears attempted-but-invalid /s/<segment> paths
         so the invalid-link toast doesn't replay on reload. */
      try{
        if(typeof location==='undefined'||!location)return;
        if(!shortLinkAttemptFromPath(location.pathname))return;
        let base=location.pathname.replace(/(?:^|\/)s\/[^\/]+\/?$/,'');
        if(!base)base='/';
        else if(base[base.length-1]!=='/')base+='/';
        history.replaceState(null,'',base+location.search);
      }catch(_){}
    }
    /* Restores /s/<slug> in the address bar after the 404.html handoff normalized it. */
    function restoreShortSharePath(slug){
      /* #303 (user 2026-09-12): a cold-opened /s/<slug> arrives via the
         404.html handoff, which normalizes the address bar to the app root.
         Put the deep link back (replaceState — no navigation, no extra
         history entry) so the URL stays shareable while the preview is open.
         No-op when the path already carries the slug (direct serve). The
         #265 Back-to-Home flow is untouched: Back pops to the root entry,
         backOutOfSharePreview clears the preview, and clearShortSharePath
         (on dismiss) still strips the slug. */
      try{
        if(typeof location==='undefined'||!location||!slug)return;
        if(shortLinkAttemptFromPath(location.pathname)===slug)return;
        const base=spaBaseForPath(location.pathname);
        history.replaceState(history.state||null,'',base+'s/'+slug+location.search);
      }catch(_){}
    }

    /* ---- 404.html SPA-fallback handoff ---- */
    function spaBaseForPath(pathname){
      /* The redirect target 404.html uses. MUST stay in sync with the
         inline copy in 404.html: project Pages serves under
         /workout-app-accounts/, prod serves at the domain root. */
      return (pathname||'').indexOf('/workout-app-accounts/')===0?'/workout-app-accounts/':'/';
    }
    /* One-shot consume of the 404.html handoff's saved path. */
    function takeSpaRedirectSlug(){
      /* One-shot consume of the 404.html handoff. Returns the attempted slug
         segment for any /s/<segment> path (#177 follow-up: malformed slugs
         must also reach the invalid-link feedback, not be silently dropped);
         anything else is ignored (the key is always cleared so it never
         replays). */
      try{
        if(typeof sessionStorage==='undefined')return null;
        const saved=sessionStorage.getItem(SPA_REDIRECT_KEY);
        if(saved!=null)sessionStorage.removeItem(SPA_REDIRECT_KEY);
        if(!saved)return null;
        const m=/^([^?#]*)/.exec(saved);
        return m?shortLinkAttemptFromPath(m[1]):null;
      }catch(_){return null;}
    }
